import{_ as n,l as r,o as a,c as l,v as t,p as s,x as o,d,i as E,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"显著性与注意力","description":"","frontmatter":{"title":"显著性与注意力","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/salience-attention.md","filePath":"econ/salience-attention.md","lastUpdated":1789023840000}'),c={name:"econ/salience-attention.md"};function h(A,e,B,_,f,m){const i=r("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="显著性与注意力" tabindex="-1">显著性与注意力 <a class="header-anchor" href="#显著性与注意力" aria-label="Permalink to &quot;显著性与注意力&quot;">​</a></h1><div class="epigraph"><p>属性被注意到才进入 $v$；税若印在价签上与若在收银台再加，需求弹性不是同一个数。</p><footer>—— Bordalo, Gennaioli and Shleifer 的显著性理论；Chetty, Looney and Kroft, AER 2009</footer></div><p><a href="/econ/nudge-choice-architecture">上一课</a>把默认当架构。本课缺口是注意力：即使没有默认切换，哪些属性被点亮也会改选择。不重写助推清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准消费者对所有价格与税同等反应。Chetty、Looney 与 Kroft（2009）：价外销售税几乎不进入需求，价内则进入——不是偏好变了，是税的显著性变了。Bordalo、Gennaioli 与 Shleifer 的显著性理论：注意力被吸引到相对突出的属性（对比上下文中特别高或特别低的维度），决策权重跟显著性走，而不是跟客观重要性走。缺口是给有限理性一个可写成权重的注意力技术，而不是再列启发式名称。</p><p>资产侧：新闻标题、涨停板、彩票型股票的偏度被点亮，平均收益可以低。定价模型后单元用有限注意力写 PEAD；本课先给微观。</p><p><span class="marginnote">显著性依赖上下文：同一属性在另一菜单里可以不再突出。这与框架近亲，但操作化是相对对比，不是收益/损失措辞。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把价值写成显著性加权的属性之和。上下文（可选菜单、近期历史）决定哪些维度突出。经验：改变税的显示、改变费用的字体与位置、改变收益率的年化与月化。预测：被点亮的弹性上升，未被点亮的接近零。</p>',9)),(a(),s(p,null,{default:o(()=>[E(i,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20NUD%5B%22%E5%8A%A9%E6%8E%A8%3A%20%E9%BB%98%E8%AE%A4%E4%B8%8E%E6%8E%92%E5%88%97%22%5D%20--%3E%20ATT%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%3A%20%E5%93%AA%E4%BA%9B%E5%B1%9E%E6%80%A7%E8%A2%AB%E7%82%B9%E4%BA%AE%22%5D%0A%20%20ATT%20--%3E%20TAX%5B%22%E4%BB%B7%E5%86%85%E7%A8%8E%20vs%20%E4%BB%B7%E5%A4%96%E7%A8%8E%22%5D%0A%20%20ATT%20--%3E%20SAL%5B%22%E6%98%BE%E8%91%97%E6%80%A7%E6%9D%83%E9%87%8D%E9%9A%8F%E4%B8%8A%E4%B8%8B%E6%96%87%E5%8F%98%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是稀疏编码。决策者不能对所有维度求梯度，只对突出维度求。显示偏好看起来菜单依赖，因为显著性是菜单的函数。家庭金融：费用比率用小字印刷时，需求对费用不敏感，对过往回报（显著）敏感——参与后的基金选择偏差。这与素养不同：素养是会不会算，显著性是算不算这一项。</p><p>不把注意力写成限价簿上的队列位置。屏幕上的盘口显著性是微观结构，本栏不写。</p><p>Chetty–Looney–Kroft 的识别是显示方式：同一法定税率，印在标价上则弹性接近价内，到收银台再加则接近忽略。BGS 把「突出」写成相对对比：菜单里特别高的属性吸走权重。基金费用用小字、过往回报用大图，需求对费用的弹性接近零——与素养不足可叠加：会算的人若没看见，仍等于没算。后课更新偏差假定信号已被看见。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>理性疏忽（Sims）用信息成本选择信号，与心理学显著性不同：前者优化互信息，后者用对比启发式。本课以 BGS 与税收现场为主。也不能把所有低弹性归因于没看见：搜寻成本、转换成本同样存在。</p><p>后课默认：信念更新的偏差，有一部分来自只更新被注意到的新闻。</p><p>同一法定税，价内进入需求、价外被忽略——弹性跟显著性走，不跟法定税率走。</p><p>会算但没看见，仍等于没算；与素养不足可叠加。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>注意力把客观属性变成进入 \\(v\\) 的子集；显著性随上下文变。</li><li>价内/价外税是同一相对价格、不同显著。</li><li>与助推分工：默认改停点，显著性改权重。</li><li>显著性依赖上下文，同一属性可不再突出。</li><li>理性疏忽优化互信息，本课以对比启发式为主。</li><li>出处：Chetty, Looney and Kroft, <em>AER</em> 2009；Bordalo, Gennaioli and Shleifer 显著性理论。</li></ul>',11))])}const S=n(c,[["render",h]]);export{T as __pageData,S as default};
